// Reshapes a transcribed voice note back into a normal WhatsApp text-message
// payload shape so the SAME normalization logic can handle it downstream.
const transcription = $input.item.json; // Groq Whisper response: { text: "..." }
const trigger = $('WA - Trigger').item.json;
const original = JSON.parse(JSON.stringify(trigger));

if (!original.messages || !original.messages[0]) {
  return [{ json: original }];
}

const msg = original.messages[0];
msg.type = 'text';
msg.text = { body: (transcription && transcription.text) ? transcription.text.trim() : '' };
delete msg.audio;

original._isTranscribedVoice = true;

return [{ json: original }];

// Turns the raw WhatsApp Cloud API webhook payload (or the reshaped
// transcribed-voice payload) into a small, flat, predictable object that
// every downstream node relies on instead of re-parsing raw webhook JSON.
//
// IMPORTANT: Meta nests BOTH real inbound messages AND delivery-status
// callbacks (sent/delivered/read, for messages THIS bot sent) under the
// same webhook field. A status callback has NO `messages` array — only
// `statuses`. If we don't tell these apart, a status event for our own
// welcome message can get mistaken for a fresh inbound message and cause
// the bot to reply to itself in a runaway loop. So: only ever treat this
// as a real inbound message if `messages[0]` genuinely exists.
const raw = $input.item.json;
const hasRealMessage = !!(raw.messages && raw.messages.length && raw.messages[0]);
const isStatusEvent = !hasRealMessage && !!(raw.statuses && raw.statuses.length);
const msg = hasRealMessage ? raw.messages[0] : {};
const contact = (raw.contacts && raw.contacts[0]) || {};
// Only present when the user has a public WhatsApp profile name set —
// not guaranteed on every contact, so downstream code must treat this
// as optional.
const profileName = (contact.profile && contact.profile.name) || null;

// Only trust senderId/messageId when this is a genuine inbound message —
// never fall back to the contacts array on a status-only event, since
// that just identifies the RECIPIENT of our own outbound send, not a
// customer sending us something.
const senderId = hasRealMessage ? (msg.from || contact.wa_id || null) : null;
const messageId = hasRealMessage ? (msg.id || null) : null;

let messageType = isStatusEvent ? 'status' : 'unsupported';
let interactionId = null;
let interactionTitle = null;
let messageText = null;

if (hasRealMessage) {
  if (msg.type === 'text' && msg.text && typeof msg.text.body === 'string') {
    messageType = 'text';
    messageText = msg.text.body;
  } else if (msg.type === 'interactive' && msg.interactive) {
    const it = msg.interactive.type;
    if (it === 'button_reply' && msg.interactive.button_reply) {
      messageType = 'button';
      interactionId = msg.interactive.button_reply.id;
      interactionTitle = msg.interactive.button_reply.title;
    } else if (it === 'list_reply' && msg.interactive.list_reply) {
      messageType = 'list';
      interactionId = msg.interactive.list_reply.id;
      interactionTitle = msg.interactive.list_reply.title;
    }
  } else if (msg.type === 'button' && msg.button) {
    // Legacy WhatsApp quick-reply template button.
    messageType = 'button';
    interactionId = msg.button.payload || msg.button.text || null;
    interactionTitle = msg.button.text || null;
  } else if (msg.type === 'audio') {
    messageType = 'audio';
  }
}

// Meta Ads "click to WhatsApp" entry point attaches a referral object to the
// FIRST inbound message. Only ever set source when it is actually present.
const referral = hasRealMessage ? (msg.referral || null) : null;
const source = referral ? 'Meta Ads' : null;

return [{
  json: {
    senderId,
    profileName,
    messageId,
    messageType,
    isStatusEvent,
    hasRealMessage,
    interactionId,
    interactionTitle,
    messageText,
    isButtonReply: messageType === 'button',
    isListReply: messageType === 'list',
    isText: messageType === 'text',
    isAudio: messageType === 'audio',
    wasVoiceMessage: !!raw._isTranscribedVoice,
    source,
    adReferral: referral,
    rawTimestamp: msg.timestamp || null,
  }
}];

// Meta/WhatsApp webhooks can redeliver the same event. We keep a small
// rolling list of already-seen WhatsApp message IDs in the workflow's
// persistent static data (this survives across separate executions,
// unlike a normal in-memory variable) and use it to drop exact repeats.
const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessageIds) staticData.seenMessageIds = [];
if (!staticData.lastProcessedAtBySender) staticData.lastProcessedAtBySender = {};
if (!staticData.lastInteractionBySender) staticData.lastInteractionBySender = {};

const id = item.messageId;
const senderId = item.senderId;
const interactionId = item.interactionId || null;
const isInteractive = !!(item.isButtonReply || item.isListReply);
let isDuplicate = false;
let dedupReason = null;

// LAYER 0 (HARD GATE): not a genuine inbound message at all — e.g. a
// delivery-status callback (sent/delivered/read) for a message THIS bot
// sent, or a webhook shape we don't recognize. These must never reach
// the routing logic, or the bot can end up replying to its own delivery
// receipts and loop on itself. This is checked before anything else.
if (!item.hasRealMessage || !senderId) {
  isDuplicate = true;
  dedupReason = item.isStatusEvent ? 'status_event' : 'no_real_message';
  return [{ json: { ...item, isDuplicate, dedupReason } }];
}

// LAYER 1: exact same WhatsApp message ID seen before.
if (id) {
  if (staticData.seenMessageIds.includes(id)) {
    isDuplicate = true;
    dedupReason = 'same_message_id';
  } else {
    staticData.seenMessageIds.push(id);
    if (staticData.seenMessageIds.length > 500) {
      staticData.seenMessageIds = staticData.seenMessageIds.slice(-500);
    }
  }
}

// LAYER 2: same button/list tap (same senderId + interactionId) seen again
// within a few seconds, even under a DIFFERENT message ID. This covers Meta
// redeliveries and WhatsApp test-number quirks that resend a single tap as
// what looks like a brand-new message. Scoped to interactive replies only,
// so it never blocks two DIFFERENT legitimate steps of the conversation
// (which always carry different interactionIds) from firing back to back.
const INTERACTION_DEDUP_WINDOW_MS = 5000;
if (!isDuplicate && senderId && interactionId && isInteractive) {
  const prev = staticData.lastInteractionBySender[senderId];
  const now = Date.now();
  if (prev && prev.interactionId === interactionId && (now - prev.at) < INTERACTION_DEDUP_WINDOW_MS) {
    isDuplicate = true;
    dedupReason = 'same_interaction_repeat';
  } else {
    staticData.lastInteractionBySender[senderId] = { interactionId, at: now };
  }
}

// LAYER 3: generic per-sender rate window, TEXT MESSAGES ONLY. Interactive
// taps are already covered by Layer 2 above with a more precise check, so
// they're excluded here — otherwise two DIFFERENT legitimate taps arriving
// within 8 seconds of each other (completely normal while filling out a
// form quickly) would get wrongly dropped as duplicates.
const SUPPRESS_WINDOW_MS = 8000;
if (!isDuplicate && senderId && !isInteractive) {
  const lastAt = staticData.lastProcessedAtBySender[senderId];
  const now = Date.now();
  if (lastAt && (now - lastAt) < SUPPRESS_WINDOW_MS) {
    isDuplicate = true;
    dedupReason = 'sender_rate_window';
  } else {
    staticData.lastProcessedAtBySender[senderId] = now;
  }
}

return [{ json: { ...item, isDuplicate, dedupReason } }];

// =================================================================
// DETERMINISTIC STATE MACHINE
// This node — plain code, not the AI — owns currentFlow, currentStep,
// button/list IDs and leadData. The AI Agent is only ever invoked as a
// side-branch (action = 'call_ai') and can never change these values.
// =================================================================

const FLOW_STEPS = {
  buy_land: ['land_size', 'location', 'budget', 'purpose'],
  construction_only: ['house_type', 'plot_available', 'location', 'budget', 'loan_required'],
  land_and_construction: ['house_type', 'location', 'budget', 'loan_required', 'time_to_start'],
  commercial_plot: ['land_size', 'location', 'budget', 'business_purpose'],
};

const COMMON_STEPS = ['contact_details'];

const STEP_DEFS = {
  land_size: { type: 'list', field: 'landSize', sectionTitle: 'Land Size',
    prompt: 'Got it! What land size are you looking for?',
    options: [
      { id: 'land_size_0_5', title: '0–5 cents' },
      { id: 'land_size_5_10', title: '5–10 cents' },
      { id: 'land_size_10_15', title: '10–15 cents' },
      { id: 'land_size_15_plus', title: '15+ cents' },
    ] },
  location: { type: 'list', field: 'location', sectionTitle: 'Location',
    prompt: 'Which location do you prefer?',
    options: [
      { id: 'location_kallekkad', title: 'Kallekkad' },
      { id: 'location_muttikulangara', title: 'Muttikulangara' },
      { id: 'location_kanjikode', title: 'Kanjikode' },
      { id: 'location_other', title: 'Others' },
    ] },
  budget: { type: 'text', field: 'budget', prompt: 'Got it. What is your budget?' },
  purpose: { type: 'list', field: 'purpose', sectionTitle: 'Purpose',
    prompt: 'What is this property for?',
    options: [
      { id: 'purpose_home', title: 'Home' },
      { id: 'purpose_investment', title: 'Investment' },
      { id: 'purpose_commercial', title: 'Commercial' },
    ] },
  house_type: { type: 'list', field: 'houseType', sectionTitle: 'House Type',
    prompt: 'What type of house are you looking for?',
    options: [
      { id: 'house_2bhk', title: '2 BHK' },
      { id: 'house_3bhk', title: '3 BHK' },
      { id: 'house_4bhk', title: '4 BHK' },
    ] },
  plot_available: { type: 'button', field: 'plotAvailable',
    prompt: 'Do you already have a plot?',
    options: [
      { id: 'plot_available_yes', title: 'Yes' },
      { id: 'plot_available_no', title: 'No' },
    ] },
  loan_required: { type: 'button', field: 'loanRequired',
    prompt: 'Will you need a home loan?',
    options: [
      { id: 'loan_yes', title: 'Yes' },
      { id: 'loan_no', title: 'No' },
    ] },
  time_to_start: { type: 'list', field: 'timeToStart', sectionTitle: 'Timeline',
    prompt: 'When would you like to start?',
    options: [
      { id: 'start_immediately', title: 'Immediately' },
      { id: 'start_3_months', title: 'Within 3 Months' },
      { id: 'start_6_months', title: 'Within 6 Months' },
      { id: 'start_just_enquiry', title: 'Just Enquiry' },
    ] },
  business_purpose: { type: 'list', field: 'businessPurpose', sectionTitle: 'Business Purpose',
    prompt: 'What will you use this plot for?',
    options: [
      { id: 'business_shop', title: 'Shop' },
      { id: 'business_office', title: 'Office' },
      { id: 'business_warehouse', title: 'Warehouse' },
      { id: 'business_other', title: 'Others' },
    ] },
  contact_details: { type: 'text', field: 'contactDetails',
    prompt: "Great! Could you share these in one message, separated by commas?\n\n1. Your Name\n2. Mobile Number (or type 'same' for this WhatsApp number)\n3. Best time to call you\n4. Any special requirement (type 'none' if not)\n\nExample: John, 9876543210, 5pm, none" },
};

const ROOT_OPTIONS = [
  { id: 'buy_land', title: 'Buy Land' },
  { id: 'construction_only', title: 'Construction Only' },
  { id: 'more_options', title: 'More Options' },
];

const MORE_OPTIONS_LIST = [
  { id: 'land_and_construction', title: 'Land + Construction' },
  { id: 'commercial_plot', title: 'Commercial Plot' },
];

const RESTART_KEYWORDS = ['start over', 'restart', 'main menu', 'menu', 'change requirement'];
const WELCOME_TEXT = 'Hi! Welcome to Cadvin Builders. How can I help you today?';

function buttonPayload(to, body, buttons) {
  return {
    messaging_product: 'whatsapp', recipient_type: 'individual', to,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: body },
      action: { buttons: buttons.map(b => ({ type: 'reply', reply: { id: b.id, title: b.title } })) },
    },
  };
}
function listPayload(to, body, buttonLabel, sectionTitle, rows) {
  return {
    messaging_product: 'whatsapp', recipient_type: 'individual', to,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: body },
      action: { button: buttonLabel, sections: [{ title: sectionTitle, rows: rows.map(r => ({ id: r.id, title: r.title })) }] },
    },
  };
}
function textPayload(to, body) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { body } };
}
function welcomePayload(to) {
  return buttonPayload(to, WELCOME_TEXT, ROOT_OPTIONS);
}
// If the customer already has a plot (construction_only flow), skip the
// location LIST and let them type their own location as free text instead.
// Everything else about the step (field name, prompt) stays the same.
function getStepDef(stepKey, leadDataRef) {
  if (stepKey === 'location' && leadDataRef && leadDataRef.plotAvailable === 'Yes') {
    return { type: 'text', field: STEP_DEFS.location.field, prompt: STEP_DEFS.location.prompt };
  }
  if (stepKey === 'location' && currentFlow === 'commercial_plot') {
    return { type: 'text', field: STEP_DEFS.location.field, prompt: STEP_DEFS.location.prompt };
  }
  return STEP_DEFS[stepKey];
}
function questionOutgoing(to, stepKey, leadDataRef) {
  const def = getStepDef(stepKey, leadDataRef);
  if (def.type === 'list') {
    return { kind: 'list', replyText: def.prompt,
      whatsappPayload: listPayload(to, def.prompt, 'Choose an option', def.sectionTitle || 'Options', def.options) };
  }
  if (def.type === 'button') {
    return { kind: 'button', replyText: def.prompt, whatsappPayload: buttonPayload(to, def.prompt, def.options) };
  }
  return { kind: 'text', replyText: def.prompt, whatsappPayload: textPayload(to, def.prompt) };
}
function reAskOutgoing(to, stepKey, prefix) {
  const def = STEP_DEFS[stepKey];
  const body = prefix + ' ' + def.prompt;
  if (def.type === 'list') {
    return { kind: 'list', replyText: body,
      whatsappPayload: listPayload(to, body, 'Choose an option', def.sectionTitle || 'Options', def.options) };
  }
  return { kind: 'button', replyText: body, whatsappPayload: buttonPayload(to, body, def.options) };
}

function isRestart(isText, lowerText) {
  return isText && RESTART_KEYWORDS.some(k => lowerText.includes(k));
}
function isPropertyQuestion(t) {
  if (!t) return false;
  const keys = ['price', 'cost', 'available', 'land', 'house', 'plot', 'project', 'brochure',
    'amenit', 'emi', 'site visit', 'near', 'location', 'sq ft', 'cent', 'offer'];
  // Malayalam property words + common Malayalam question markers, so voice/text
  // messages in Malayalam reach the AI agent the same way English ones do.
  const malayalamKeys = ['വില', 'ചെലവ്', 'ഭൂമി', 'സ്ഥലം', 'വീട്', 'പ്ലോട്ട്', 'പ്രോജക്റ്റ്',
    'ബ്രോഷർ', 'സൗകര്യ', 'ഇഎംഐ', 'ഗഡു', 'സൈറ്റ് വിസിറ്റ്', 'സന്ദർശ', 'അടുത്ത്',
    'ലൊക്കേഷൻ', 'സെന്റ്', 'ഓഫർ', 'ലോൺ',
    'എപ്പോൾ', 'എവിടെ', 'എത്ര', 'ഉണ്ടോ', 'ആണോ', 'എന്താണ്', 'എങ്ങനെ'];
  return t.includes('?') || keys.some(k => t.includes(k)) || malayalamKeys.some(k => t.includes(k));
}
function extractYesNo(t) {
  if (/\bno\b|nope|illa\b|venda\b|not required|dont need|don't need/.test(t)) return 'no';
  if (/\byes\b|yeah|yep|\bya\b|athe\b|venam\b|need|required/.test(t)) return 'yes';
  return null;
}
function extractLandSizeBucket(t) {
  const m = t.match(/(\d+(\.\d+)?)/);
  if (!m) return null;
  const val = parseFloat(m[1]);
  if (val <= 5) return 'land_size_0_5';
  if (val <= 10) return 'land_size_5_10';
  if (val <= 15) return 'land_size_10_15';
  return 'land_size_15_plus';
}

// ------------------------- input -------------------------
const item = $input.item.json;
const to = item.senderId;
const state = item.state || {};
let currentFlow = state.currentFlow || null;
let currentStep = state.currentStep || null;
let leadData = state.leadData || {};
let leadSaved = !!state.leadSaved;
const rowExists = !!state.rowExists;

const isText = !!item.isText;
const isButtonReply = !!item.isButtonReply;
const isListReply = !!item.isListReply;
const interactionId = item.interactionId || null;
const interactionTitle = item.interactionTitle || null;
const rawText = (item.messageText || '').trim();
const lowerText = rawText.toLowerCase();

// Prevent a burst of separate initial webhook events (common around
// Click-to-WhatsApp / Meta Ads entry) from sending multiple welcome menus.
// A real new conversation still gets the first menu; an immediate duplicate
// greeting/referral event is silently ignored for this short debounce window.
const GREETING_KEYWORDS = [
  'hi', 'hello', 'hey', 'hi there', 'good morning',
  'good afternoon', 'good evening', 'start'
];
const RECENT_WELCOME_WINDOW_MS = 15000;
const lastStateUpdateMs = state.updatedAt ? Date.parse(state.updatedAt) : NaN;
const recentWelcome =
  Number.isFinite(lastStateUpdateMs) &&
  (Date.now() - lastStateUpdateMs >= 0) &&
  (Date.now() - lastStateUpdateMs < RECENT_WELCOME_WINDOW_MS);
const isSimpleGreeting = isText &&
  GREETING_KEYWORDS.some(k => lowerText === k || lowerText.startsWith(k + ' '));

let action = 'send';
let outgoing = null;
let resumePrompt = null;
let leadCompleted = false;
let completedLead = null;

// ------------------------- routing -------------------------
if (isRestart(isText, lowerText)) {
  const keep = {};
  ['name', 'mobileNumber', 'whatsappNumber', 'leadId', 'createdAt', 'source'].forEach(k => {
    if (leadData[k]) keep[k] = leadData[k];
  });
  leadData = keep;
  currentFlow = null;
  currentStep = null;
  outgoing = { kind: 'button', replyText: "No problem, let's start again.\\n\\n" + WELCOME_TEXT,
    whatsappPayload: welcomePayload(to) };

} else if (!currentFlow) {
  // ---- ROOT LEVEL: no active flow ----
  if (isButtonReply && ['buy_land', 'construction_only'].includes(interactionId)) {
    currentFlow = interactionId;
    leadData.requirementType = interactionTitle;
    leadData.leadId = leadData.leadId || (to + '_' + Date.now());
    leadData.createdAt = leadData.createdAt || new Date().toISOString();
    if (item.source) leadData.source = item.source;
    currentStep = FLOW_STEPS[currentFlow][0];
    outgoing = questionOutgoing(to, currentStep, leadData);

  } else if (isButtonReply && interactionId === 'more_options') {
    currentFlow = 'more_options';
    currentStep = 'option_selection';
    outgoing = { kind: 'list', replyText: 'Sure, here are more options:',
      whatsappPayload: listPayload(to, 'Please choose one:', 'Choose an option', 'More Options', MORE_OPTIONS_LIST) };

  } else if (recentWelcome && (isSimpleGreeting || !!item.source)) {
    // A near-simultaneous second Meta/greeting event was already welcomed.
    // Do not send another interactive menu.
    action = 'noop';

  } else if (!rowExists) {
    // Brand-new WhatsApp number (Meta Ad entry or genuinely first contact):
    // greet exactly once for the initial event.
    outgoing = { kind: 'button', replyText: WELCOME_TEXT, whatsappPayload: welcomePayload(to) };

  } else if (isText && isPropertyQuestion(lowerText)) {
    action = 'call_ai';

  } else if (isText && !isSimpleGreeting) {
    // Returning customer, no active flow, and it's not a plain "hi/hello" —
    // most likely a genuine question (e.g. just finished a lead and is
    // asking something else). Let the AI answer instead of just re-showing
    // the welcome menu again.
    action = 'call_ai';

  } else {
    outgoing = { kind: 'button', replyText: WELCOME_TEXT, whatsappPayload: welcomePayload(to) };
  }

} else if (currentFlow === 'more_options' && currentStep === 'option_selection') {
  if (isListReply && ['land_and_construction', 'commercial_plot'].includes(interactionId)) {
    currentFlow = interactionId;
    leadData.requirementType = interactionTitle;
    leadData.leadId = leadData.leadId || (to + '_' + Date.now());
    leadData.createdAt = leadData.createdAt || new Date().toISOString();
    if (item.source) leadData.source = item.source;
    currentStep = FLOW_STEPS[currentFlow][0];
    outgoing = questionOutgoing(to, currentStep, leadData);
  } else if (isText && isPropertyQuestion(lowerText)) {
    action = 'call_ai';
  } else {
    outgoing = { kind: 'list', replyText: "Sorry, I didn't quite get that. Please choose one:",
      whatsappPayload: listPayload(to, "Sorry, I didn't quite get that. Please choose one:", 'Choose an option', 'More Options', MORE_OPTIONS_LIST) };
  }

} else if (currentStep === 'pending_completion') {
  // A previous attempt to save this lead did not yet confirm success.
  // Retry the completion instead of asking the customer anything new.
  leadCompleted = true;

} else {
  // ---- INSIDE A STRUCTURED FLOW OR COMMON LEAD-CAPTURE PHASE ----
  const flowSteps = FLOW_STEPS[currentFlow] || [];
  const isCommonStep = COMMON_STEPS.includes(currentStep);
  const def = getStepDef(currentStep, leadData);

  function advance() {
    if (!isCommonStep) {
      const idx = flowSteps.indexOf(currentStep);
      if (idx > -1 && idx < flowSteps.length - 1) {
        currentStep = flowSteps[idx + 1];
        outgoing = questionOutgoing(to, currentStep, leadData);
        return;
      }
      currentStep = COMMON_STEPS[0];
      outgoing = questionOutgoing(to, currentStep, leadData);
      return;
    }
    const idx = COMMON_STEPS.indexOf(currentStep);
    if (idx > -1 && idx < COMMON_STEPS.length - 1) {
      currentStep = COMMON_STEPS[idx + 1];
      outgoing = questionOutgoing(to, currentStep, leadData);
      return;
    }
    leadCompleted = true;
  }

  if (def.type === 'list' || def.type === 'button') {
    const validIds = def.options.map(o => o.id);
    if ((def.type === 'list' && isListReply && validIds.includes(interactionId)) ||
        (def.type === 'button' && isButtonReply && validIds.includes(interactionId))) {
      leadData[def.field] = interactionTitle;
      advance();

    } else if (isText && currentStep === 'land_size') {
      const bucketId = extractLandSizeBucket(lowerText);
      if (bucketId) {
        leadData[def.field] = def.options.find(o => o.id === bucketId).title;
        advance();
      } else if (isPropertyQuestion(lowerText)) {
        action = 'call_ai'; resumePrompt = def.prompt;
      } else {
        outgoing = reAskOutgoing(to, currentStep, 'Sorry, could you pick one of the options below?');
      }

    } else if (isText && (currentStep === 'plot_available' || currentStep === 'loan_required')) {
      const yn = extractYesNo(lowerText);
      if (yn) {
        leadData[def.field] = yn === 'yes' ? 'Yes' : 'No';
        advance();
      } else if (isPropertyQuestion(lowerText)) {
        action = 'call_ai'; resumePrompt = def.prompt;
      } else {
        outgoing = reAskOutgoing(to, currentStep, 'Please tap Yes or No below:');
      }

    } else if (isText && isPropertyQuestion(lowerText)) {
      action = 'call_ai'; resumePrompt = def.prompt;

    } else {
      outgoing = reAskOutgoing(to, currentStep, "Sorry, that doesn't look right.");
    }

  } else {
    // text-type step: budget, name, mobile_number, preferred_time_to_call, special_requirement
    let answer = null;
    if (isText && rawText) answer = rawText;
    else if ((isButtonReply || isListReply) && interactionTitle) answer = interactionTitle;

    if (answer && currentStep === 'contact_details') {
      const parts = answer.split(',').map(p => p.trim()).filter(Boolean);
      leadData.name = parts[0] || answer;
      leadData.mobileNumber = (parts[1] && /^(same|this number|whatsapp number|use this)/i.test(parts[1])) ? to : (parts[1] || '');
      leadData.preferredTimeToCall = parts[2] || '';
      leadData.specialRequirement = (parts[3] && /^(none|no|nil|nothing)$/i.test(parts[3])) ? 'None' : (parts[3] || '');
      advance();
    } else if (answer && currentStep === 'mobile_number' && /^(same|this number|whatsapp number|use this)/i.test(answer)) {
      leadData.mobileNumber = to;
      advance();
    } else if (answer && currentStep === 'special_requirement' && /^(none|no|nil|nothing)$/i.test(answer.trim())) {
      leadData.specialRequirement = 'None';
      advance();
    } else if (answer) {
      leadData[def.field] = answer;
      advance();
    } else {
      outgoing = { kind: 'text', replyText: def.prompt, whatsappPayload: textPayload(to, def.prompt) };
    }
  }
}

if (leadCompleted) {
  // Capture is complete. Do not persist buyer data here; CRM will be connected later.
  action = 'complete_lead';
  leadData.whatsappNumber = to;
  completedLead = { ...leadData };
  const thankYou = 'Thank you for contacting Cadvin Builders. Our Sales Executive will contact you shortly.';
  outgoing = { kind: 'text', replyText: thankYou, whatsappPayload: textPayload(to, thankYou) };
  currentFlow = null;
  currentStep = null;
  leadData = {};
}

const updatedState = {
  whatsappNumber: to,
  currentFlow,
  currentStep,
  leadData,
  leadSaved,
  lastInteractionId: item.messageId,
  updatedAt: new Date().toISOString(),
};

return [{
  json: {
    ...item,
    action,
    outgoing,
    resumePrompt,
    completedLead,
    state: updatedState,
  }
}];

// Wraps whatever the AI Agent produced into the same {outgoing.whatsappPayload}
// shape every other branch uses, so a single WhatsApp send node can handle
// all of them. The AI is never allowed to touch currentFlow/currentStep —
// we simply pass the state through unchanged (aside from bookkeeping).
const agentOut = $input.item.json;
const route = $('WA - Route Message').item.json;
const to = route.senderId;

function textPayload(to, body) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { body } };
}

let text;
if (agentOut.error) {
  text = "Sorry, I'm having a little trouble right now — could you please repeat that?";
} else {
  text = agentOut.output || 'Sorry, could you please repeat that?';
  if (route.resumePrompt) {
    text = text + '\\n\\n' + route.resumePrompt;
  }
}

return [{
  json: {
    ...route,
    outgoing: { kind: 'text', replyText: text, whatsappPayload: textPayload(to, text) },
  }
}];

// Load per-WhatsApp conversation state from n8n workflow static data.
const item = $input.item.json;
const store = $getWorkflowStaticData('global');
if (!store.conversationStates) store.conversationStates = {};
const senderId = String(item.senderId || '');
const saved = senderId ? (store.conversationStates[senderId] || null) : null;
const state = saved ? {
  currentFlow: saved.currentFlow || null, currentStep: saved.currentStep || null,
  leadData: saved.leadData || {}, leadSaved: !!saved.leadSaved, rowExists: true,
  lastInteractionId: saved.lastInteractionId || null, updatedAt: saved.updatedAt || null,
  earlyCaptureSent: !!saved.earlyCaptureSent, crmRecordId: saved.crmRecordId || null,
} : { currentFlow:null, currentStep:null, leadData:{}, leadSaved:false, rowExists:false, lastInteractionId:null, updatedAt:null,
  earlyCaptureSent:false, crmRecordId:null };
return [{json:{...item,state}}];

// Save only conversation state. Buyer/lead persistence is intentionally delegated to the future CRM.
//
// FIX (state-persistence bug): this node used to read $input.item.json for
// senderId/state. But this node sits AFTER "WA - Send Response", an HTTP
// Request node — so $input.item.json here was the Meta/WhatsApp API HTTP
// response (message id, contacts, etc.), NOT the routing result produced by
// "WA - Route Message". senderId was always undefined, so this function
// returned before ever writing to the store, and state never persisted
// between turns (every message looked like a brand-new conversation).
//
// Fix: pull senderId/state directly from the route context node, which is
// always upstream in this same execution regardless of which branch
// (send / call_ai -> AI - Format AI Response / complete_lead) led here.
const httpResponse = $input.item.json;
const route = $('WA - Route Message').item.json;
const store = $getWorkflowStaticData('global');
if (!store.conversationStates) store.conversationStates = {};
const senderId = String(route.senderId || '');
const state = route.state || {};
if (!senderId) return [{json: httpResponse}];
const existingEntry = store.conversationStates[senderId] || {};
store.conversationStates[senderId] = {
  currentFlow: state.currentFlow || null, currentStep: state.currentStep || null,
  leadData: (state.currentFlow || state.currentStep) ? (state.leadData || {}) : {},
  leadSaved: false, lastInteractionId: state.lastInteractionId || route.messageId || null,
  updatedAt: state.updatedAt || new Date().toISOString(),
  // Preserve early-capture flags set by the parallel Meta-ad
  // early-capture branch (see "CRM - Save Early Capture State"),
  // which may have run earlier in this same execution.
  earlyCaptureSent: existingEntry.earlyCaptureSent || !!state.earlyCaptureSent,
  crmRecordId: existingEntry.crmRecordId || state.crmRecordId || null,
};
const keys=Object.keys(store.conversationStates);
if(keys.length>2000){
  keys.sort((a,b)=>String(store.conversationStates[a].updatedAt||'').localeCompare(String(store.conversationStates[b].updatedAt||'')));
  for(const k of keys.slice(0,keys.length-2000)) delete store.conversationStates[k];
}
return [{json: httpResponse}];

const route = $('WA - Route Message').item.json;
const lead = route.completedLead || {};

// Cadvin's CRM only has 3 purpose IDs — Commercial Plot has no dedicated one,
// so it's mapped to "Land Only" as the closest match, per your call.
const PURPOSE_MAP = {
  'Buy Land': 1,
  'Land + Construction': 2,
  'Construction Only': 3,
  'Commercial Plot': 1,
};

// CRM requires whatsapp as exactly 10 digits, no country code
function last10Digits(raw) {
  return String(raw || '').replace(/\D/g, '').slice(-10);
}

// buy_land and commercial_plot flows never ask about a loan, but the CRM
// requires loan_required on every lead — defaults to "Maybe" when not asked.
const loanRequired = lead.loanRequired === 'Yes' ? 'Yes'
  : lead.loanRequired === 'No' ? 'No'
  : 'Maybe';

// Anything collected that has no matching CRM field gets folded into "message"
const extra = [
  lead.landSize && `Land size: ${lead.landSize}`,
  lead.houseType && `House type: ${lead.houseType}`,
  lead.purpose && `Purpose: ${lead.purpose}`,
  lead.businessPurpose && `Business purpose: ${lead.businessPurpose}`,
  lead.timeToStart && `Time to start: ${lead.timeToStart}`,
  lead.source && `Source: ${lead.source}`,
].filter(Boolean).join(' | ');

const payload = {
  name: lead.name || 'WhatsApp Lead',
  whatsapp: last10Digits(lead.whatsappNumber),
  purpose: PURPOSE_MAP[lead.requirementType] || 1,
  location: lead.location || 'Not specified',
  loan_required: loanRequired,
  phone: lead.mobileNumber || '',
  budget: lead.budget || '',
  best_time: lead.preferredTimeToCall || '',
  special_requirement: lead.specialRequirement || '',
  message: extra,
};

return [{ json: payload }];

const res = $input.item.json;
const ok = res && (res.success === true);
if (!ok) {
  console.log('CRM PUSH FAILED:', JSON.stringify(res));
} else {
  console.log('CRM push OK for lead');
}
return [{ json: res }];

// Early capture: as soon as someone arrives via a Meta "Click to
// WhatsApp" ad, push a minimal CRM record with just their name +
// number, before they've answered any lead-qualification questions.
// Required CRM fields we don't know yet get placeholder defaults and
// are corrected later once the full lead is collected (see
// "CRM - Route Create or Update").
const item = $input.item.json;

function last10Digits(raw) {
  return String(raw || '').replace(/\D/g, '').slice(-10);
}

const payload = {
  name: item.profileName || 'WhatsApp Lead (early capture)',
  whatsapp: last10Digits(item.senderId),
  purpose: 1, // placeholder: "Buy Land" - corrected when the full lead completes
  location: 'Not specified', // placeholder - corrected when the full lead completes
  loan_required: 'Maybe', // placeholder - corrected when the full lead completes
  phone: '',
  budget: '',
  best_time: '',
  special_requirement: '',
  message: 'Early capture from Meta Ad click - full lead details pending',
};

return [{ json: { ...item, crmPayload: payload } }];

// Mark this sender's early-capture as done so we never push a second
// "early capture" row on their next message, and remember whatever ID
// the CRM gave back (if any) for a future update call once Cadvin's
// team ships a PATCH/update endpoint.
//
// TODO(update-endpoint): once Cadvin confirms the update endpoint and
// how it matches records (by ID vs by phone), wire it into
// "CRM - Route Create or Update" using the crmRecordId captured here.
const res = $input.item.json;
const senderId = String($('WA - Normalize Incoming').item.json.senderId || '');
const store = $getWorkflowStaticData('global');
if (!store.conversationStates) store.conversationStates = {};
if (senderId) {
  const existing = store.conversationStates[senderId] || {};
  // Response shape from Cadvin's API isn't documented for the ID field,
  // so check common shapes defensively rather than assuming one.
  const crmRecordId = (res && (res.id ?? res.data?.id ?? res.enquiry?.id ?? res.enquiry_id)) ?? null;
  store.conversationStates[senderId] = {
    ...existing,
    earlyCaptureSent: true,
    crmRecordId: crmRecordId,
  };
  if (!(res && res.success === true)) {
    console.log('EARLY CAPTURE CRM PUSH FAILED for', senderId, ':', JSON.stringify(res));
  } else {
    console.log('Early capture CRM push OK for', senderId, 'crmRecordId:', crmRecordId);
  }
}
return [{ json: res }];

// No PATCH/update endpoint exists yet on Cadvin's CRM (as of this
// build). This sender was already created via early-capture, so
// pushing the full lead here as another POST would create a
// DUPLICATE enquiry row instead of updating the existing one.
// Until Cadvin's team ships an update endpoint, we deliberately do
// NOT call the CRM again here - we just log the complete lead data
// so it can be merged manually, or swapped for a real update call
// once the endpoint exists.
//
// TODO(update-endpoint): replace this node with an httpRequest
// PATCH/PUT call to Cadvin's update endpoint once available, using:
//   crmRecordId = $('WA - Route Message').item.json.state.crmRecordId
// to identify which record to update (or the phone number, if
// that's how their update endpoint matches records instead).
const fullLead = $input.item.json;
const crmRecordId = $('WA - Route Message').item.json.state.crmRecordId || null;
console.log('MANUAL CRM UPDATE NEEDED - crmRecordId:', crmRecordId, 'fullLead:', JSON.stringify(fullLead));
return [{ json: { needsManualCrmUpdate: true, crmRecordId, fullLead } }];
